parameters.jsonBody:
={{ (() => {
  const optionalText = value => {
    if (value === null || value === undefined) return null;
    const text = String(value).trim();
    return !text || /^(null|undefined)$/i.test(text) ? null : text;
  };
  const rawAmount = $fromAI('amount', 'Monto numérico de la transacción, sin símbolos ni separadores de miles');
  const amount = typeof rawAmount === 'number' ? rawAmount : Number(String(rawAmount ?? '').trim());
  if (rawAmount === null || rawAmount === undefined || String(rawAmount).trim() === '' || !Number.isFinite(amount) || amount <= 0) {
    throw new Error('INVALID_AMOUNT: proporciona un monto numérico mayor que cero.');
  }
  let items = $fromAI('items', 'Arreglo de ítems con concept, category, amount, quantity y unit_price. Para un registro sin desglose, usa [].');
  if (items === null || items === undefined || items === '') items = [];
  if (typeof items === 'string') {
    try { items = JSON.parse(items); }
    catch { throw new Error('INVALID_ITEMS_JSON: el detalle debe ser un arreglo JSON válido. No se envió la transacción.'); }
  }
  if (!Array.isArray(items) || items.some(item => item === null || typeof item !== 'object' || Array.isArray(item))) {
    throw new Error('INVALID_ITEMS_JSON: el detalle debe ser un arreglo de objetos. No se envió la transacción.');
  }
  return {
    p_channel_type: 'whatsapp',
    p_channel_code: $('Webhook').first().json.body.entry[0].changes[0].value.messages[0].from.toString(),
    p_type: $fromAI('type', 'expense si es gasto o income si es ingreso'),
    p_concept: $fromAI('concept', 'Descripción o concepto del gasto o ingreso'),
    p_category_key: $fromAI('category_key', 'Categoría estandarizada en minúsculas y snake_case'),
    p_amount: amount,
    p_household_name: optionalText($fromAI('household_name', 'Nombre del hogar o null si no se especificó')),
    p_transaction_date: null,
    p_auxiliar_code: optionalText($fromAI('auxliar', 'Código o nombre del auxiliar, o null si no se especificó')),
    p_items: items
  };
})() }}
